/**
 * @summary List all cook sessions
 */
export const getListCooksUrl = (params?: ListCooksParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/cooks?${stringifiedParams}`
    : `/api/cooks`;
};

export const listCooks = async (
  params?: ListCooksParams,
  options?: RequestInit,
): Promise<Cook[]> => {
  return customFetch<Cook[]>(getListCooksUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getListCooksQueryKey = (params?: ListCooksParams) => {
  return [`/api/cooks`, ...(params ? [params] : [])] as const;
};

export const getListCooksQueryOptions = <
  TData = Awaited<ReturnType<typeof listCooks>>,
  TError = ErrorType<unknown>,
>(
  params?: ListCooksParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listCooks>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getListCooksQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof listCooks>>> = ({
    signal,
  }) => listCooks(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof listCooks>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

